import ast
from app.services import users


def _check_node(node):
    if isinstance(node, ast.Expression):
        return _check_node(node.body)
    elif isinstance(node, ast.Compare):
        if not all(isinstance(op, (ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE)) for op in node.ops):
            return False
        if not _check_node(node.left):
            return False
        for comp in node.comparators:
            if not _check_node(comp):
                return False
        return True
    elif isinstance(node, ast.BoolOp):
        if not isinstance(node.op, (ast.And, ast.Or)):
            return False
        return all(_check_node(v) for v in node.values)
    elif isinstance(node, ast.UnaryOp):
        if not isinstance(node.op, ast.Not):
            return False
        return _check_node(node.operand)
    elif isinstance(node, ast.Name):
        return node.id in ('id', 'name', 'email')
    elif isinstance(node, ast.Constant):
        return isinstance(node.value, (int, str))
    else:
        return False


def _evaluate(node, user):
    if isinstance(node, ast.Expression):
        return _evaluate(node.body, user)
    elif isinstance(node, ast.Compare):
        v = _evaluate(node.left, user)
        for i, op in enumerate(node.ops):
            right = _evaluate(node.comparators[i], user)
            if isinstance(op, ast.Eq):
                if not (v == right): return False
            elif isinstance(op, ast.NotEq):
                if not (v != right): return False
            elif isinstance(op, ast.Lt):
                if not (v < right): return False
            elif isinstance(op, ast.LtE):
                if not (v <= right): return False
            elif isinstance(op, ast.Gt):
                if not (v > right): return False
            elif isinstance(op, ast.GtE):
                if not (v >= right): return False
            v = right
        return True
    elif isinstance(node, ast.BoolOp):
        if isinstance(node.op, ast.And):
            return all(_evaluate(v, user) for v in node.values)
        elif isinstance(node.op, ast.Or):
            return any(_evaluate(v, user) for v in node.values)
    elif isinstance(node, ast.UnaryOp):
        if isinstance(node.op, ast.Not):
            return not _evaluate(node.operand, user)
    elif isinstance(node, ast.Name):
        return user[node.id]
    elif isinstance(node, ast.Constant):
        return node.value
    raise ValueError("Unsupported node")


def handle_filter_users(params: dict) -> tuple[int, dict]:
    where = params.get("where")
    if not isinstance(where, str):
        return 400, {"error": "invalid filter"}
    try:
        tree = ast.parse(where, mode='eval')
        if not _check_node(tree):
            return 400, {"error": "invalid filter"}

        all_users = users.get_all_users()
        filtered_users = []
        for user in all_users:
            if _evaluate(tree, user):
                filtered_users.append(user)

        filtered_users.sort(key=lambda u: u["id"])
        return 200, {"users": filtered_users}
    except Exception:
        return 400, {"error": "invalid filter"}

